CREATE TABLE IF NOT EXISTS avci_mobile_apps (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, app_key TEXT NOT NULL, name TEXT NOT NULL, platform TEXT NOT NULL, bundle_id TEXT NOT NULL, current_version TEXT NOT NULL DEFAULT '1.0.0', build_number TEXT NOT NULL DEFAULT '1', release_channel TEXT NOT NULL DEFAULT 'production', store_status TEXT NOT NULL DEFAULT 'draft', store_url TEXT NOT NULL DEFAULT '', health_status TEXT NOT NULL DEFAULT 'unknown', last_heartbeat_at TEXT NOT NULL DEFAULT '', minimum_os_version TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(app_key, platform), CHECK(platform IN ('ios','android')), CHECK(store_status IN ('draft','review','published','rejected','withdrawn')));
CREATE INDEX IF NOT EXISTS idx_avci_mobile_apps_status ON avci_mobile_apps(status, platform);
CREATE TABLE IF NOT EXISTS customer_mobile_app_assignments (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, customer_id INTEGER NOT NULL, mobile_app_id INTEGER NOT NULL, license_id INTEGER NOT NULL DEFAULT 0, branded_name TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'assigned', assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(customer_id, mobile_app_id));
CREATE INDEX IF NOT EXISTS idx_customer_mobile_app_status ON customer_mobile_app_assignments(customer_id, status);
